func resourceApikeysKeyDecoder(d *schema.ResourceData, meta interface{}, res map[string]interface{}) (map[string]interface{}, error) {
	// A deleted API key is soft-deleted: a GET keeps returning it with a deleteTime set until it
	// is permanently purged (up to 30 days later). Treat a key that has a deleteTime as gone so
	// Terraform (and the acceptance-test destroy check) see it as deleted rather than dangling.
	if v, ok := res["deleteTime"]; ok && v != nil && v != "" {
		return nil, nil
	}

	return res, nil
}

func ResourceApikeysKeyFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("display_name", flattenApikeysKeyDisplayName(res["displayName"], d, config)); err != nil {
		return fmt.Errorf("Error reading Key: %s", err)
	}
	if err = d.Set("uid", flattenApikeysKeyUid(res["uid"], d, config)); err != nil {
		return fmt.Errorf("Error reading Key: %s", err)
	}
	if err = d.Set("service_account_email", flattenApikeysKeyServiceAccountEmail(res["serviceAccountEmail"], d, config)); err != nil {
		return fmt.Errorf("Error reading Key: %s", err)
	}
	if err = d.Set("annotations", flattenApikeysKeyAnnotations(res["annotations"], d, config)); err != nil {
		return fmt.Errorf("Error reading Key: %s", err)
	}
	if err = d.Set("restrictions", flattenApikeysKeyRestrictions(res["restrictions"], d, config)); err != nil {
		return fmt.Errorf("Error reading Key: %s", err)
	}
	if err = d.Set("effective_annotations", flattenApikeysKeyEffectiveAnnotations(res["annotations"], d, config)); err != nil {
		return fmt.Errorf("Error reading Key: %s", err)
	}

	return nil
}
